@props(['name', 'label', 'value' => '', 'required' => false, 'rows' => 3, 'maxlength' => 5000])
@php($fieldId = str_replace(['.', '[', ']'], '-', $name))
<div><label for="{{ $fieldId }}" class="block text-sm font-medium mb-2">{{ $label }} @if($required)<span class="text-red-700" aria-hidden="true">*</span>@endif</label><textarea id="{{ $fieldId }}" name="{{ str_contains($name, '.') ? 'additional_data['.\Illuminate\Support\Str::after($name, '.').']' : $name }}" rows="{{ $rows }}" maxlength="{{ $maxlength }}" @required($required) @if($errors->has($name)) aria-invalid="true" aria-describedby="{{ $fieldId }}-error" @endif class="w-full border border-forest/25 rounded-lg p-3 text-base">{{ old($name, $value) }}</textarea>@error($name)<p id="{{ $fieldId }}-error" class="text-sm text-red-700 mt-2">{{ $message }}</p>@enderror</div>
